-- Step 1 of 5 for orders.public_id. Catalog-only: no table rewrite, no scan.
-- The default is set before the backfill so rows inserted from now on are filled by the database.
-- gen_random_uuid() (v4) rather than uuidv7(): v7 embeds a timestamp and sorts by creation time,
-- which would leak the same ordering information the sequential id does.
SET LOCAL lock_timeout = '5s';

ALTER TABLE orders ADD COLUMN public_id uuid;
ALTER TABLE orders ALTER COLUMN public_id SET DEFAULT gen_random_uuid();

