-- migrate:no-transaction
-- Step 2 of 5: backfill orders.public_id for existing rows.
--
-- Runs outside a transaction block so that each batch COMMITs and releases its row locks.
-- Each batch is one short UPDATE over a primary-key range, so row locks are held for milliseconds.
-- Rows the app updates concurrently are simply locked for the length of one batch.
--
-- Idempotent: the WHERE public_id IS NULL filter means a rerun after a failure resumes where it
-- stopped. The runner does not record this file if it fails, so the deploy can retry it.
SET lock_timeout = '5s';

DO $$
DECLARE
  chunk constant bigint := 5000;
  lower_id bigint := 0;
  max_id bigint;
BEGIN
  SELECT coalesce(max(id), 0) INTO max_id FROM orders;
  WHILE lower_id <= max_id LOOP
    UPDATE orders
       SET public_id = gen_random_uuid()
     WHERE id >= lower_id AND id < lower_id + chunk AND public_id IS NULL;
    lower_id := lower_id + chunk;
    COMMIT;
  END LOOP;
END
$$;

RESET lock_timeout;

